            this.TRUE_LEAK = `replacement`;
            this.TRUE_OBSOLETE = `replacementlogic`;

            // EUR 24M transition cap and the 10% EBIT floor (current margin 12%).
            this.BUDGET_CAP = 24;
            this.MARGIN_FLOOR = 10;
            this.START_MARGIN = 12;

            // Each pattern: value function + whether it conflicts with keeping sell-more-units.
            this.PATTERN_FUNCTION = {
                leasing: `unlocking`,
                takeback: `sharing`,
                reman: `maintaining`,
                repair: `maintaining`,
                modular: `maintaining`,
                sellmore: `conflict`
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    eco: 12,
                    social: 10,
                    margin: 12.0,
                    fit: 0,
                    budgetUsed: 0,
                    floorBreached: false,
                    patternsPicked: [],
                    ecoHistory: [12],
                    socialHistory: [10],
                    marginHistory: [12.0],
                    fitHistory: [0],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    leak: `replacement`,
                    obsolete: `replacementlogic`,
                    honesty: 60,
                    patterns: [],
                    func: `balanced`,
                    revenue: `hybrid`,
                    redesign: 6,
                    logistics: 5,
                    refurb: 6,
                    platform: 5,
                    phasing: `phased`,
                    owner: `evidence`,
                    investor: `metrics`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const leak = document.getElementById(`leakInput`);
                const obs = document.getElementById(`obsoleteInput`);
                const hon = document.getElementById(`honestyInput`);
                if (leak) decisions.leak = leak.value;
                if (obs) decisions.obsolete = obs.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const ids = [
                    [`patLeasing`, `leasing`], [`patTakeback`, `takeback`], [`patReman`, `reman`],
                    [`patRepair`, `repair`], [`patModular`, `modular`], [`patSellmore`, `sellmore`]
                ];
                const picked = [];
                ids.forEach(([elId, val]) => {
                    const el = document.getElementById(elId);
                    if (el && el.checked) picked.push(val);
                });
                decisions.patterns = picked;
                const fn = document.getElementById(`functionInput`);
                if (fn) decisions.func = fn.value;
                if (picked.length !== 3) {
                    warn(`warn_pattern_count`); return false;
                }
            } else if (round === 3) {
                const rev = document.getElementById(`revenueInput`);
                if (rev) decisions.revenue = rev.value;
                const fields = [[`redesignInput`, `redesign`], [`logisticsInput`, `logistics`], [`refurbInput`, `refurb`], [`platformInput`, `platform`]];
                fields.forEach(([elId, key]) => {
                    const el = document.getElementById(elId);
                    if (el) decisions[key] = parseFloat(el.value);
                });
                const vals = [decisions.redesign, decisions.logistics, decisions.refurb, decisions.platform];
                if (vals.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = vals.reduce((a, b) => a + b, 0);
                if (total > this.BUDGET_CAP + 0.001) {
                    warn(`warn_over_budget`); return false;
                }
            } else if (round === 4) {
                const ph = document.getElementById(`phasingInput`);
                const ow = document.getElementById(`ownerInput`);
                const iv = document.getElementById(`investorInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ph) decisions.phasing = ph.value;
                if (ow) decisions.owner = ow.value;
                if (iv) decisions.investor = iv.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let ecoDelta = 0, socialDelta = 0, marginDelta = 0, fitDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the value logic. The real leak is the replacement cycle; the real
                // obsolescence is the replacement LOGIC. Honesty = willingness to redesign the
                // model rather than bolt on a feature (Common Error 1).
                if (d.leak === this.TRUE_LEAK) { fitDelta += 14; ecoDelta += 4; coachKey = `coach_r1_leak_right`; }
                else { fitDelta -= 6; coachKey = `coach_r1_leak_wrong`; }

                if (d.obsolete === this.TRUE_OBSOLETE) { fitDelta += 12; coachKey = (d.leak === this.TRUE_LEAK) ? `coach_r1_diag_sharp` : coachKey; }
                else { fitDelta -= 4; }

                if (d.honesty >= 60) { fitDelta += 10; }
                else if (d.honesty <= 25) { fitDelta -= 8; coachKey = `coach_r1_boltonrisk`; }

                summaryKey = (d.leak === this.TRUE_LEAK && d.obsolete === this.TRUE_OBSOLETE) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Select & combine patterns, tagged by value function (Common Errors 2 & 5).
                const picks = d.patterns || [];
                ds.patternsPicked = picks.slice();
                const keepsSellMore = picks.indexOf(`sellmore`) !== -1;

                // Score each chosen pattern's TBL contribution.
                const ECO = { leasing: 8, takeback: 9, reman: 10, repair: 7, modular: 8, sellmore: -4 };
                const SOC = { leasing: 6, takeback: 4, reman: 6, repair: 12, modular: 3, sellmore: -2 };
                picks.forEach((p) => { ecoDelta += (ECO[p] || 0); socialDelta += (SOC[p] || 0); });

                // Combinability: a coherent maintaining+unlocking+sharing mix reinforces; keeping
                // sell-more-units alongside access cannibalises (Common Error 5).
                const functions = picks.map((p) => this.PATTERN_FUNCTION[p]);
                const distinct = functions.filter((f, i) => f !== `conflict` && functions.indexOf(f) === i).length;

                if (keepsSellMore) {
                    fitDelta -= 18; coachKey = `coach_r2_conflict`;
                    ecoDelta -= 2;
                } else if (distinct >= 3) {
                    fitDelta += 20; coachKey = `coach_r2_coherent`;
                } else if (distinct === 2) {
                    fitDelta += 10; coachKey = `coach_r2_partial`;
                } else {
                    fitDelta += 2; coachKey = `coach_r2_narrow`;
                }

                // Value-function discipline (Common Error 2). Untagged picking caps fit gains.
                if (d.func === `untagged`) {
                    fitDelta = Math.min(fitDelta, 0); fitDelta -= 6; coachKey = `coach_r2_untagged`;
                } else if (d.func === `balanced` && !keepsSellMore && distinct >= 3) {
                    fitDelta += 6;
                }

                // A shortlist with NO maintaining pattern leaves the durable-tool asset unused.
                if (functions.indexOf(`maintaining`) === -1 && !keepsSellMore) {
                    ecoDelta -= 4; coachKey = `coach_r2_nomaintain`;
                }

                summaryKey = (!keepsSellMore && distinct >= 2 && d.func !== `untagged`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Redesign the value proposition, choose the revenue model, allocate the €24M.
                const redesign = d.redesign, logistics = d.logistics, refurb = d.refurb, platform = d.platform;
                const total = redesign + logistics + refurb + platform;
                ds.budgetUsed = Math.round(total * 10) / 10;

                // Investment converts to ecological/social value — but only with the right model.
                // Refurb capacity is the main social-value (repair-jobs) lever.
                ecoDelta += Math.round((redesign * 1.3 + logistics * 1.4 + refurb * 1.1) * 10) / 10;
                socialDelta += Math.round((refurb * 1.8 + platform * 1.0) * 10) / 10;
                fitDelta += Math.round((redesign + platform) * 0.8);

                // Revenue model effect on margin (the decisive tension). Leasing/subscription takes
                // on inventory + financing risk that compresses near-term EBIT (Common Error 3).
                switch (d.revenue) {
                    case `hybrid`:
                        marginDelta += 0.6; ecoDelta += 4; socialDelta += 3; fitDelta += 10; coachKey = `coach_r3_hybrid`; break;
                    case `leasing`:
                        marginDelta -= 5.5; ecoDelta += 8; socialDelta += 5; fitDelta += 4; coachKey = `coach_r3_leasing`; break;
                    case `payperuse`:
                        marginDelta -= 4.0; ecoDelta += 6; socialDelta += 4; fitDelta += 2; coachKey = `coach_r3_payperuse`; break;
                    case `resale`:
                        marginDelta += 1.0; ecoDelta += 5; socialDelta += 4; fitDelta += 6; coachKey = `coach_r3_resale`; break;
                    case `sale`:
                        marginDelta += 1.5; ecoDelta -= 8; socialDelta -= 6; fitDelta -= 12; coachKey = `coach_r3_sale`; break;
                }

                // Under-funding the loop: high-impact patterns chosen but starved of reverse
                // logistics / refurb cannot deliver — impact is hollow and fit suffers.
                if ((d.revenue === `leasing` || d.revenue === `resale` || d.revenue === `hybrid`) && (logistics + refurb) < 6) {
                    ecoDelta = Math.round(ecoDelta * 0.5);
                    socialDelta = Math.round(socialDelta * 0.5);
                    coachKey = `coach_r3_starved`;
                }

                // Leaving most of the €24M unspent = timidity; the transformation under-resources.
                if (total < 14) { fitDelta -= 6; ecoDelta -= 3; coachKey = `coach_r3_underspend`; }

                summaryKey = (d.revenue === `hybrid` || d.revenue === `resale`) ? `sum_r3_good` : (d.revenue === `sale` ? `sum_r3_token` : `sum_r3_risky`);
            } else if (round === 4) {
                // Present & defend. Phasing protects the floor; owner/investor answers decide
                // whether the model is credible (Common Errors 3 & 4 & 5/ignoring social).
                switch (d.phasing) {
                    case `phased`:
                        marginDelta += 3.5; fitDelta += 10; ecoDelta += 4; socialDelta += 3; coachKey = `coach_r4_phased`; break;
                    case `bigbang`:
                        marginDelta -= 3.0; ecoDelta += 6; socialDelta += 4; fitDelta -= 4; coachKey = `coach_r4_bigbang`; break;
                    case `slow`:
                        marginDelta += 2.5; ecoDelta -= 8; socialDelta -= 6; fitDelta -= 10; coachKey = `coach_r4_slow`; break;
                }

                if (d.owner === `evidence`) { marginDelta += 1.5; fitDelta += 8; }
                else if (d.owner === `promise`) { fitDelta -= 8; coachKey = `coach_r4_promise`; }
                else if (d.owner === `retreat`) { marginDelta += 1.0; ecoDelta -= 10; socialDelta -= 8; fitDelta -= 12; coachKey = `coach_r4_retreat`; }

                if (d.investor === `metrics`) { ecoDelta += 6; socialDelta += 8; fitDelta += 8; }
                else if (d.investor === `story`) { fitDelta -= 6; coachKey = (d.owner === `evidence`) ? `coach_r4_story` : coachKey; }
                else if (d.investor === `ecoonly`) { socialDelta -= 12; fitDelta -= 6; coachKey = `coach_r4_ecoonly`; }

                // The team's conviction that economics is part of sustainability nudges fit.
                fitDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.phasing === `phased` && d.owner === `evidence` && d.investor === `metrics`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with clamps.
            ds.eco = Math.max(0, Math.min(100, ds.eco + ecoDelta));
            ds.social = Math.max(0, Math.min(100, ds.social + socialDelta));
            ds.fit = Math.max(0, Math.min(100, ds.fit + fitDelta));
            ds.margin = Math.round((ds.margin + marginDelta) * 10) / 10;
            if (ds.margin < 0) ds.margin = 0;

            if (ds.margin < this.MARGIN_FLOOR) ds.floorBreached = true;

            ds.ecoHistory.push(Math.round(ds.eco));
            ds.socialHistory.push(Math.round(ds.social));
            ds.marginHistory.push(ds.margin);
            ds.fitHistory.push(Math.round(ds.fit));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            var res = {
                period: state.currentPeriod,
                eco: Math.round(ds.eco),
                ecoDelta: Math.round(ecoDelta),
                social: Math.round(ds.social),
                socialDelta: Math.round(socialDelta),
                margin: ds.margin,
                marginDelta: Math.round(marginDelta * 10) / 10,
                fit: Math.round(ds.fit),
                floorBreached: ds.floorBreached,
                budgetUsed: ds.budgetUsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
            // Expose composite to the reporting/grading layer each period (results_utils.php reads
            // domainState.performance.overallScore); period 4 locks the authoritative score.
            ds.performance = { overallScore: this._composite(ds) };
            return res;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`ecoDisplay`, `domainState.eco`, (v) => Math.round(v));
            uiManager.bind(`socialDisplay`, `domainState.social`, (v) => Math.round(v));
            uiManager.bind(`fitDisplay`, `domainState.fit`, (v) => Math.round(v));
            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const card = document.querySelector(`.patternsim-card-margin`);
                if (card) {
                    card.classList.toggle(`patternsim-margin-breach`, Number(v) < this.MARGIN_FLOOR);
                    card.classList.toggle(`patternsim-margin-safe`, Number(v) >= this.MARGIN_FLOOR);
                }
                return Number(v).toFixed(1) + `%`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => `€` + Number(v).toFixed(1) + `M / €24.0M`);

            const self = this;
            const hon = document.getElementById(`honestyInput`);
            const honReadout = document.getElementById(`honestyReadout`);
            if (hon && honReadout) {
                honReadout.textContent = hon.value;
                hon.addEventListener(`input`, function() { honReadout.textContent = hon.value; });
            }

            const allocIds = [`redesignInput`, `logisticsInput`, `refurbInput`, `platformInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = `€` + total.toFixed(1) + `M`;
                const bar = document.querySelector(`.patternsim-alloc-readout`);
                if (bar) bar.style.color = (total > self.BUDGET_CAP) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        getChartConfig() {
            return {
