                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Ecological Value`,
                                data: [],
                                borderColor: `#2e9e63`,
                                backgroundColor: `rgba(46,158,99,0.15)`,
