                                data: [],
                                borderColor: `#2f80c0`,
                                backgroundColor: `rgba(47,128,192,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f80c0`,
